const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var client = std.http.Client{ .allocator = allocator };
    defer client.deinit();

    const api_key = "5b2fc71e-a3cc-41a6-8475-6da0aaccec21";

    const payload =
        \\{"query":"computer-use agent, general-purpose AI agent, digital worker, autonomous AI agent","includeDomains":["apps.apple.com/hu"],"numResults":100,"type":"instant","contents":{"summary":{"query":"mindent magyarul \u00edrj"},"extras":{"links":1}}}
    ;

    const uri = std.Uri.parse("") catch unreachable;

    var server_header_buffer: [16384]u8 = undefined;
    var req = try client.open(.POST, uri, .{
        .server_header_buffer = &server_header_buffer,
        .extra_headers = &[_]std.http.Header{
            .{ .name = "Content-Type", .value = "application/json" },
            .{ .name = "x-api-key", .value = api_key },
            .{ .name = "accept", .value = "application/json" },
        },
    });
    defer req.deinit();

    req.transfer_encoding = .{ .content_length = payload.len };

    try req.send();
    try req.writeAll(payload);
    try req.finish();
    try req.wait();

    const status = req.response.status;
    const status_int = @intFromEnum(status);
    try std.io.getStdOut().writer().print("HTTP Status: {d}\n", .{status_int});

    var response_body = std.ArrayList(u8).init(allocator);
    defer response_body.deinit();

    try req.reader().readAllArrayList(&response_body, 100 * 1024 * 1024);

    try std.io.getStdOut().writer().print("{s}\n", .{response_body.items});
}
