const std = @import("std");

fn getEnvOwned(allocator: std.mem.Allocator, name: []const u8) ![]u8 {
    return std.process.getEnvVarOwned(allocator, name);
}

fn jsonEscapeString(writer: anytype, s: []const u8) !void {
    try writer.writeByte('"');
    for (s) |c| {
        switch (c) {
            '"' => try writer.writeAll("\\\""),
            '\\' => try writer.writeAll("\\\\"),
            '\n' => try writer.writeAll("\\n"),
            '\r' => try writer.writeAll("\\r"),
            '\t' => try writer.writeAll("\\t"),
            0x08 => try writer.writeAll("\\b"),
            0x0c => try writer.writeAll("\\f"),
            else => {
                if (c < 0x20) {
                    try writer.print("\\u{X:0>4}", .{@as(u16, c)});
                } else {
                    try writer.writeByte(c);
                }
            },
        }
    }
    try writer.writeByte('"');
}

fn appendChatRequestBody(buffer: *std.ArrayList(u8)) !void {
    const writer = buffer.writer();
    try writer.writeByte('{');
    try jsonEscapeString(writer, "messages");
    try writer.writeByte(':');
    try writer.writeByte('[');
    try writer.writeByte('{');
    try jsonEscapeString(writer, "role");
    try writer.writeByte(':');
    try jsonEscapeString(writer, "system");
    try writer.writeByte(',');
    try jsonEscapeString(writer, "content");
    try writer.writeByte(':');
    try jsonEscapeString(writer, "");
    try writer.writeByte('}');
    try writer.writeByte(']');
    try writer.writeByte(',');
    try jsonEscapeString(writer, "model");
    try writer.writeByte(':');
    try jsonEscapeString(writer, "qwen-3-235b-a22b-instruct-2507");
    try writer.writeByte(',');
    try jsonEscapeString(writer, "stream");
    try writer.writeByte(':');
    try writer.writeAll("true");
    try writer.writeByte(',');
    try jsonEscapeString(writer, "max_completion_tokens");
    try writer.writeByte(':');
    try writer.writeAll("20000");
    try writer.writeByte(',');
    try jsonEscapeString(writer, "temperature");
    try writer.writeByte(':');
    try writer.writeAll("1.01");
    try writer.writeByte(',');
    try jsonEscapeString(writer, "top_p");
    try writer.writeByte(':');
    try writer.writeAll("0.8");
    try writer.writeByte('}');
}

fn extractDeltaContent(allocator: std.mem.Allocator, data: []const u8) !?[]u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, data, .{});
    defer parsed.deinit();

    const root = parsed.value;
    if (root != .object) return null;

    const choices_value = root.object.get("choices") orelse return null;
    if (choices_value != .array) return null;
    if (choices_value.array.items.len == 0) return null;

    const first_choice = choices_value.array.items;
    if (first_choice != .object) return null;

    const delta_value = first_choice.object.get("delta") orelse return null;
    if (delta_value != .object) return null;

    const content_value = delta_value.object.get("content") orelse return null;
    if (content_value == .null) return null;
    if (content_value != .string) return null;

    return try allocator.dupe(u8, content_value.string);
}

fn processSseStream(reader: anytype, writer: anytype, allocator: std.mem.Allocator) !void {
    var line_buffer = std.ArrayList(u8).init(allocator);
    defer line_buffer.deinit();

    var data_buffer = std.ArrayList(u8).init(allocator);
    defer data_buffer.deinit();

    while (true) {
        line_buffer.clearRetainingCapacity();
        reader.streamUntilDelimiter(line_buffer.writer(), '\n', null) catch |err| switch (err) {
            error.EndOfStream => {
                if (data_buffer.items.len != 0) {
                    const maybe_content = try extractDeltaContent(allocator, data_buffer.items);
                    if (maybe_content) |content| {
                        defer allocator.free(content);
                        try writer.writeAll(content);
                    }
                }
                return;
            },
            else => return err,
        };

        if (line_buffer.items.len > 0 and line_buffer.items[line_buffer.items.len - 1] == '\r') {
            _ = line_buffer.pop();
        }

        if (line_buffer.items.len == 0) {
            if (data_buffer.items.len != 0) {
                const maybe_content = try extractDeltaContent(allocator, data_buffer.items);
                if (maybe_content) |content| {
                    defer allocator.free(content);
                    try writer.writeAll(content);
                }
                data_buffer.clearRetainingCapacity();
            }
            continue;
        }

        if (std.mem.startsWith(u8, line_buffer.items, "data:")) {
            var payload = std.mem.trimLeft(u8, line_buffer.items["data:".len..], " ");
            if (std.mem.eql(u8, payload, "[DONE]")) {
                return;
            }
            if (data_buffer.items.len != 0) {
                try data_buffer.append('\n');
            }
            try data_buffer.appendSlice(payload);
        }
    }
}

pub fn main() !void {
    var gpa_state = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa_state.deinit();
    const allocator = gpa_state.allocator();

    const api_key = try getEnvOwned(allocator, "CEREBRAS_API_KEY");
    defer allocator.free(api_key);

    var body = std.ArrayList(u8).init(allocator);
    defer body.deinit();
    try appendChatRequestBody(&body);

    var client = std.http.Client{ .allocator = allocator };
    defer client.deinit();

    const uri = try std.Uri.parse("");

    var server_header_buffer: u8 = undefined;
    var req = try client.open(.POST, uri, .{
        .server_header_buffer = &server_header_buffer,
        .extra_headers = &[_]std.http.Header{
            .{ .name = "content-type", .value = "application/json" },
            .{ .name = "accept", .value = "text/event-stream" },
            .{ .name = "authorization", .value = try std.fmt.allocPrint(allocator, "Bearer {s}", .{api_key}) },
        },
    });
    defer {
        for (req.extra_headers) |header| {
            if (std.mem.eql(u8, header.name, "authorization")) {
                allocator.free(header.value);
            }
        }
        req.deinit();
    }

    req.transfer_encoding = .{ .content_length = body.items.len };

    try req.send();
    try req.writeAll(body.items);
    try req.finish();
    try req.wait();

    try processSseStream(req.reader(), std.io.getStdOut().writer(), allocator);
}
